//! Approval specification, action-binding verification, and nonce tracking.
//!
//! Enforces Invariant 5:
//! Approvals are bound to exact op + args + target identity + requesting device + nonce + expiry.
//! Any alteration invalidates the approval.
#![forbid(unsafe_code)]

use ciborium::value::Value;
use dumer_proto::codec::compute_request_hash;
use dumer_proto::registry::RiskTier;
use dumer_proto::types::{ApprovalRef, SignerRole, SubjectIdentity};
use serde::{Deserialize, Serialize};
use std::collections::{BTreeMap, HashSet};

use crate::error::ApprovalError;

/// Specification generated by the policy broker when an operation requires explicit approval.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ApprovalSpec {
    pub approval_id: [u8; 16],
    pub request_hash: [u8; 32],
    pub op: String,
    pub args_summary: String,
    pub subject_identity: Option<SubjectIdentity>,
    pub risk_tier: RiskTier,
    pub effects: Vec<String>,
    pub nonce: [u8; 16],
    pub expires_at: u64,
    pub required_signers: Vec<SignerRole>,
}

/// Signed approval record from a specific signer.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct SignerApproval {
    pub signer: SignerRole,
    pub device_id: String,
    pub signature: Vec<u8>,
}

/// Tracks consumed nonces to prevent replay attacks.
#[derive(Debug, Clone, Default)]
pub struct NonceTracker {
    consumed: HashSet<[u8; 16]>,
}

impl NonceTracker {
    pub fn new() -> Self {
        Self {
            consumed: HashSet::new(),
        }
    }

    /// Verifies that a nonce has not been consumed yet, and marks it as used.
    pub fn check_and_mark_used(&mut self, nonce: &[u8; 16]) -> Result<(), ApprovalError> {
        if self.consumed.contains(nonce) {
            return Err(ApprovalError::ReplayedNonce);
        }
        self.consumed.insert(*nonce);
        Ok(())
    }
}

/// Validates an incoming signed approval against the expected operation, arguments, and subject.
pub struct ApprovalValidator;

impl ApprovalValidator {
    /// Validates an approval reference against the exact invocation context.
    pub fn validate(
        approval: &ApprovalRef,
        expected_op: &str,
        expected_args: &BTreeMap<String, Value>,
        expected_subject: Option<&SubjectIdentity>,
        expected_device_id: Option<&str>,
        current_time: u64,
    ) -> Result<(), ApprovalError> {
        // 1. Check expiration (judged strictly by laptop clock)
        if current_time > approval.signature.expires_at {
            return Err(ApprovalError::Expired {
                expired_at: approval.signature.expires_at,
                current_time,
            });
        }

        // 2. Check device binding if a device was expected
        if let Some(expected_device) = expected_device_id {
            if approval.signature.device_id != expected_device {
                return Err(ApprovalError::DeviceMismatch {
                    expected: expected_device.to_string(),
                    actual: approval.signature.device_id.clone(),
                });
            }
        }

        // 3. Recompute canonical request hash over (op, args, subject)
        let recomputed_hash = compute_request_hash(expected_op, expected_args, expected_subject)
            .map_err(|e| ApprovalError::Internal(e.to_string()))?;

        // 4. Verify hash binding (Invariant 5)
        if recomputed_hash != approval.signature.request_hash {
            return Err(ApprovalError::HashMismatch);
        }

        // 5. Signature payload integrity check
        if approval.signature.sig.is_empty() {
            return Err(ApprovalError::Internal(
                "Approval signature payload is empty".to_string(),
            ));
        }

        Ok(())
    }
}
